/// </summary>
[ExtensionOf(classStr(PrintMgmtDelegatesHandler))]
final class METPrintMgmtDelegatesHandler_Extension
{
}

Method.Source:
    /// <summary>
    /// Determines the party type for a journal records and the current document type.
    /// </summary>
    /// <param name="_docType">
    /// Type of the document.
    /// </param>
    /// <param name="_jour">
    /// A journal record.
    /// </param>
    /// <returns>
    /// A member of <c>PrintMgmtPrintDestinationPartyType</c>.
    /// </returns>
    /// <exception cref="Exception::Error">
    /// An invalid combination of journal record and document type was found.
    /// </exception>
    protected static PrintMgmtPrintDestinationPartyType getPartyType(PrintMgmtDocumentType _docType, Common _jour)
    {
        PrintMgmtPrintDestinationPartyType  destinationPartyType = next getPartyType(_docType, _jour);

        if(_docType == PrintMgmtDocumentType::METCustActivityStatement)
        {
            destinationPartyType = PrintMgmtPrintDestinationPartyType::Customer;
        }

        return destinationPartyType;
    }
